31	export function pickNextCue(rng: RNG, config: DrillConfig): CueDef {
32	  if (config.distanceAxisEnabled) {
33	    const pool = filterByAllowed(CUE_LIBRARY, config.allowedCueIds)
34	    if (pool.length === 0) {
35	      throw new Error('pickNextCue: empty library after allowedCueIds filter')
36	    }
37	    return pool[Math.floor(rng() * pool.length)]
38	  }
39	  const allowedGo = filterByAllowed(GO_CUES, config.allowedCueIds)
40	  const allowedNoGo = filterByAllowed(NO_GO_CUES, config.allowedCueIds)
41	  const goEmpty = allowedGo.length === 0
42	  const noGoEmpty = allowedNoGo.length === 0
43	  if (goEmpty && noGoEmpty) {
44	    throw new Error('pickNextCue: empty allowedCueIds filter')
45	  }
46	  const wantGo = goEmpty ? false : noGoEmpty ? true : rng() < config.goCueProbability
47	  const pool = wantGo ? allowedGo : allowedNoGo
48	  return pool[Math.floor(rng() * pool.length)]
49	}
