215	export interface CueBreakdownRow {
216	  cueId: CueDef['id']
217	  reps: number
218	  correct: number
219	  falseStarts: number
220	  hesitations: number
221	  lateMisses: number
222	  avgRtMs: number | null
223	  best10AvgRtMs: number | null
