226	/**
227	 * Mean of the (up to) 10 fastest values. Returns null if the input is empty.
228	 * Phase 5 — single source of truth for the best-10 metric, used by
229	 * cueBreakdown, sessionTrend (per-session best-10), and cueAggregate
230	 * (cross-session best-10).
231	 */
232	export function best10AvgOf(times: number[]): number | null {
233	  if (times.length === 0) return null
234	  const sorted = [...times].sort((a, b) => a - b).slice(0, 10)
235	  return Math.round(sorted.reduce((a, b) => a + b, 0) / sorted.length)
236	}
237	
238	/**
239	 * Reps whose result is correct_go AND whose reactionMs is a real number.
240	 * Single source of truth for the "RT-eligible" rep set; reused by
241	 * cueBreakdown here and by every analytics aggregate.
242	 */
243	export function correctGoTimesOf(reps: RepRecord[]): number[] {
244	  return reps
245	    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
246	    .map((r) => r.reactionMs as number)
247	}
248	
249	export function cueBreakdown(reps: RepRecord[]): CueBreakdownRow[] {
250	  const byId = new Map<CueDef['id'], RepRecord[]>()
251	  for (const r of reps) {
252	    const list = byId.get(r.cueId) ?? []
253	    list.push(r)
254	    byId.set(r.cueId, list)
255	  }
256	  return Array.from(byId.entries()).map(([cueId, list]) => {
257	    const correctGoTimes = correctGoTimesOf(list)
258	    const avgRtMs =
259	      correctGoTimes.length === 0
260	        ? null
261	        : Math.round(
262	            correctGoTimes.reduce((a, b) => a + b, 0) / correctGoTimes.length,
263	          )
264	    return {
265	      cueId,
266	      reps: list.length,
267	      correct: list.filter(
268	        (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
269	      ).length,
270	      falseStarts: list.filter((r) => r.result === 'false_start').length,
271	      hesitations: list.filter((r) => r.result === 'hesitation').length,
272	      lateMisses: list.filter((r) => r.result === 'late').length,
273	      avgRtMs,
274	      best10AvgRtMs: best10AvgOf(correctGoTimes),
275	    }
276	  })
277	}
