279	export type PriorGoStreakBucket = '0' | '1' | '2' | '3+'
280	
281	export interface AntiRhythmStats {
282	  overallFalseStartRate: number
283	  buckets: Record<PriorGoStreakBucket, { falseStarts: number; total: number }>
284	  narrative: string
285	}
286	
287	function priorGoStreakBucketOf(n: number): PriorGoStreakBucket {
288	  if (n <= 0) return '0'
289	  if (n === 1) return '1'
290	  if (n === 2) return '2'
291	  return '3+'
292	}
293	
294	export function antiRhythmSignal(reps: RepRecord[]): AntiRhythmStats {
295	  const buckets: AntiRhythmStats['buckets'] = {
296	    '0': { falseStarts: 0, total: 0 },
297	    '1': { falseStarts: 0, total: 0 },
298	    '2': { falseStarts: 0, total: 0 },
299	    '3+': { falseStarts: 0, total: 0 },
300	  }
301	  let streak = 0
302	  let totalGoReps = 0
303	  let totalFalseStarts = 0
304	  for (const r of reps) {
305	    if (r.isGo) {
306	      const b = priorGoStreakBucketOf(streak)
307	      buckets[b].total += 1
308	      if (r.result === 'false_start') buckets[b].falseStarts += 1
309	      totalGoReps += 1
310	      if (r.result === 'false_start') totalFalseStarts += 1
311	      streak += 1
312	    } else {
313	      streak = 0
314	    }
315	  }
316	  const overallFalseStartRate =
317	    totalGoReps === 0 ? 0 : totalFalseStarts / totalGoReps
318	
319	  let narrative = 'No rhythm pattern detected.'
320	  let bestBucket: PriorGoStreakBucket | null = null
321	  let bestRate = -1
322	  for (const key of Object.keys(buckets) as PriorGoStreakBucket[]) {
323	    const b = buckets[key]
324	    if (b.total < 3) continue
325	    const rate = b.falseStarts / b.total
326	    if (
327	      rate > bestRate &&
328	      overallFalseStartRate > 0 &&
329	      rate >= overallFalseStartRate * 1.5
330	    ) {
331	      bestRate = rate
332	      bestBucket = key
333	    }
334	  }
335	  if (bestBucket !== null) {
336	    const pct = Math.round(bestRate * 100)
337	    const label =
338	      bestBucket === '0'
339	        ? 'a non-go cue'
340	        : bestBucket === '3+'
341	          ? '3+ consecutive go cues'
342	          : `${bestBucket} consecutive go cue${bestBucket === '1' ? '' : 's'}`
343	    narrative = `False starts most often after ${label} (${pct}%).`
344	  }
345	
346	  return { overallFalseStartRate, buckets, narrative }
347	}
348	
349	export function summarize(reps: RepRecord[]): SessionSummary {
350	  const reactionTimes = reps
351	    .filter((r) => r.result === 'correct_go' && r.reactionMs !== null)
352	    .map((r) => r.reactionMs as number)
353	
354	  const avgReactionMs =
355	    reactionTimes.length === 0
356	      ? null
357	      : Math.round(
358	          reactionTimes.reduce((a, b) => a + b, 0) / reactionTimes.length,
359	        )
360	
361	  return {
362	    reps: reps.length,
363	    correct: reps.filter(
364	      (r) => r.result === 'correct_go' || r.result === 'correct_no_go',
365	    ).length,
366	    falseStarts: reps.filter((r) => r.result === 'false_start').length,
367	    lateMisses: reps.filter((r) => r.result === 'late').length,
368	    hesitations: reps.filter((r) => r.result === 'hesitation').length,
369	    score: reps.reduce((a, r) => a + r.score, 0),
370	    avgReactionMs,
371	  }
372	}
